function cinemaLibraryRelink(id){const item=(cinemaInit().library||[]).find(x=>x&&x.id===id);if(!item)return;const accept=item.kind==='video'?'video/mp4,video/webm,video/quicktime,.mp4,.webm,.m4v':'.txt,.md,.epub,text/plain,text/markdown,application/epub+zip';pickFile(accept,async f=>{try{if(item.kind==='video'){const key=cinemaStoreKey('video',item.mediaKey);await cinPut(key,f);item.storeKey=key;item.source='idb';item.size=+f.size||0;item.fileName=f.name||'';}else{const isEpub=/\.epub$/i.test(f.name||''),text=isEpub?await cinemaDecodeEpub(f):cinemaDecodeText(await f.arrayBuffer());if(!text)throw new Error('作品正文为空');const key=cinemaStoreKey('book',item.mediaKey);await cinPut(key,text);item.storeKey=key;item.source='idb';item.size=+f.size||0;item.fileName=f.name||'';}item.updatedAt=Date.now();save();closeModal();toast('源文件已重新保存，可以继续了');render();}catch(e){toast((e&&e.message)||'保存失败');}});}
function cinemaLibraryRename(id){const item=(cinemaInit().library||[]).find(x=>x&&x.id===id);if(!item)return;const s=(S.cinema.sessions||[]).slice().reverse().find(x=>x&&x.mediaKey===item.mediaKey);if(s){closeModal();cinemaRename(s.id);return;}openModal(`<h3>修改名字</h3><div class="field"><input id="cinLibraryRename" maxlength="80" value="${esc(item.title||'')}"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="cinemaLibraryRenameSave('${item.id}')">保存</button></div>`);}
function cinemaLibraryRenameSave(id){const item=(cinemaInit().library||[]).find(x=>x&&x.id===id),name=((($('#cinLibraryRename')||{}).value)||'').trim().replace(/[\r\n]+/g,' ').slice(0,80);if(!item||!name){toast('名字不能为空');return;}item.title=name;item.updatedAt=Date.now();(S.cinema.sessions||[]).filter(x=>x&&x.mediaKey===item.mediaKey).forEach(x=>x.title=name);const p=S.cinema.progress[item.mediaKey];if(p)p.title=name;save();closeModal();render();toast('名字已保存');}
async function cinemaDeleteStoredSubtitles(mediaKey){if(!mediaKey)return;const x=cinemaInit(),taskKey=cinemaStoreKey('asr-task',mediaKey),jobKey=cinemaStoreKey('asr-job',mediaKey),manualKey=cinemaStoreKey('subtitle-file',mediaKey);delete x.asrTasks[taskKey];(x.sessions||[]).filter(s=>s&&s.mediaKey===mediaKey).forEach(s=>{delete s.subtitleName;delete s.subtitleCount;delete s.subtitleSource;});if(_cin.mediaKey===mediaKey){_cin.token++;_cin.extracting=false;_cin.asrMode='';_cin.asrCoveredUntil=0;_cin.asrGuardPaused=false;_cin.cues=_cin.cues.filter(c=>c&&c.source==='speech');_cin.subtitleName='';}await cinDel(jobKey);await cinDel(manualKey);}
async function cinemaLibraryDelete(id){const item=(cinemaInit().library||[]).find(x=>x&&x.id===id),video=item&&item.kind==='video',message=video?'从视频盒移除《'+item.title+'》？\n本机视频、已提取的完整/部分字幕和提取进度都会删除；观看记录和角色记忆仍会保留。':'从书架移除《'+(item&&item.title||'')+'》？\n作品正文会从本机删除；阅读记录和角色记忆仍会保留。';if(!item||!await uiConfirm(message))return;S.cinema.library=S.cinema.library.filter(x=>x&&x.id!==id);const contentKey=item.storeKey||cinemaStoreKey(item.kind,item.mediaKey),subtitleDelete=video?cinemaDeleteStoredSubtitles(item.mediaKey):Promise.resolve();save();await Promise.all([cinDel(contentKey),subtitleDelete]);closeModal();render();toast(video?'已移出视频盒，视频和字幕已删除':'已移出书架，作品正文已删除');}
function cinemaFindLibrary(title){title=String(title||'').trim();const rows=(cinemaInit().library||[]).filter(x=>x&&x.source!=='missing'&&x.source!=='saving');return rows.find(x=>x.title===title)||rows.find(x=>x.title&&title&&(x.title.includes(title)||title.includes(x.title)))||null;}
function cinemaInviteCard(cid,item,role){const c=getC(cid);if(!c||!item)return null;const card={role:role==='assistant'?'assistant':'user',type:'cinemainvite',title:item.title||'未命名',kind:item.kind||'video',libraryId:item.id,status:'pending',byRole:role==='assistant',time:Date.now(),id:uid()};msgs(cid).push(card);if(card.role==='assistant')notifyIncoming(c,card);save();refreshChatMessages(cid);return card;}
function cinemaInviteLibrary(id){const item=(cinemaInit().library||[]).find(x=>x&&x.id===id),c=cinemaRole();if(!item||!c)return toast('先选择陪同角色');const card=cinemaInviteCard(c.id,item,'user');if(!card)return;closeModal();openChat(c.id);toast('邀请卡已发送，等待 '+(c.remark||c.name)+' 回应');if(!c.blocked)scheduleReply(c.id,'[系统：'+S.me.name+'刚通过放映室邀请卡邀请你'+(item.kind==='book'?'共读':'一起看')+'《'+item.title+'》。请按你真实的性格和当下关系决定。愿意就单独输出 [同意放映] 并自然回应；不愿意就单独输出 [拒绝放映] 并说一句自然理由。]');}
function cinemaRoleInvite(cid,title){const item=cinemaFindLibrary(title),c=getC(cid);if(!item||!c)return false;cinemaInviteCard(cid,item,'assistant');return true;}
function cinemaRoleAnswerInvite(cid,ok){const card=[...msgs(cid)].reverse().find(x=>x&&x.role==='user'&&x.type==='cinemainvite'&&x.status==='pending');if(!card)return false;card.status=ok?'accepted':'declined';card.answeredAt=Date.now();save();refreshChatMessages(cid);return true;}
async function cinemaRespondInvite(cid,mid,ok){const c=getC(cid),card=msgs(cid).find(x=>x&&x.id===mid&&x.type==='cinemainvite');if(!c||!card||card.status!=='pending')return;card.status=ok?'accepted':'declined';card.answeredAt=Date.now();msgs(cid).push({role:'user',type:'sys',content:ok?'🎬 '+S.me.name+'接受了《'+card.title+'》的放映室邀请':'🎬 '+S.me.name+'拒绝了《'+card.title+'》的放映室邀请',time:Date.now(),id:uid(),_silent:true});save();if(!ok){render();scheduleReply(cid,'[系统：'+S.me.name+'拒绝了你发来的《'+card.title+'》放映室邀请。按你本人性格自然回应一句，不要继续假装已经进入放映室。]');return;}cinemaInit().selectedCid=cid;save();await cinemaOpenInviteCard(cid,mid);}
async function cinemaOpenInviteCard(cid,mid){const card=msgs(cid).find(x=>x&&x.id===mid&&x.type==='cinemainvite'),item=card&&(cinemaInit().library||[]).find(x=>x&&x.id===card.libraryId);if(!card||card.status!=='accepted')return toast('邀请还没有被同意');if(!item||item.source==='missing'||item.source==='saving')return toast('源文件暂不可用，请先在放映室重新关联');cinemaInit().selectedCid=cid;save();await cinemaLibraryPlay(item.id,false);}
function cinemaParseTime(v){const p=String(v||'').trim().replace(',','.').split(':').map(Number);if(p.some(n=>!Number.isFinite(n)))return NaN;return p.length===3?p[0]*3600+p[1]*60+p[2]:p.length===2?p[0]*60+p[1]:NaN;}
function cinemaParseSubtitles(raw){const lines=String(raw||'').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').replace(/^WEBVTT[^\n]*\n+/i,'').split('\n'),out=[];for(let i=0;i<lines.length;i++){const timing=String(lines[i]||'').trim();if(!timing.includes('-->'))continue;const sides=timing.split('-->'),start=cinemaParseTime(sides[0]),end=cinemaParseTime(String(sides[1]||'').trim().split(/\s+/)[0]);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)continue;const body=[];let j=i+1;for(;j<lines.length;j++){const row=String(lines[j]||'').trim();if(!row)break;if(row.includes('-->'))break;if(/^\d+$/.test(row)&&String(lines[j+1]||'').includes('-->'))break;body.push(row);}const text=body.join(' ').replace(/<[^>]+>/g,'').replace(/\{\\[^}]+\}/g,'').trim();if(text)out.push({start,end,text:text.slice(0,500)});i=Math.max(i,j-1);}return out.sort((a,b)=>a.start-b.start);}
function cinemaCueAt(t){let hit=null;for(const cue of _cin.cues){if(cue.start>t)break;if(t<=cue.end)hit=cue;}return hit;}
function cinemaSubtitleContext(t){return _cin.cues.filter(x=>x.source!=='speech'&&x.start<=t+.5&&x.end>=Math.max(0,t-90)).slice(-18).map(x=>'['+cinemaFmt(x.start)+'] '+x.text).join('\n');}
function cinemaApplyCues(cues,name,source){cues=(cues||[]).map(x=>Object.assign({},x,{source:source||x.source||'subtitle'})).filter(x=>Number.isFinite(x.start)&&Number.isFinite(x.end)&&x.end>x.start&&x.text);const speech=_cin.cues.filter(x=>x&&x.source==='speech');_cin.cues=cues.concat(speech).sort((a,b)=>a.start-b.start);_cin.subtitleName=name||'字幕';const s=cinemaSession();if(s){s.subtitleName=_cin.subtitleName;s.subtitleCount=cues.length;s.subtitleSource=source||'subtitle';s.updatedAt=Date.now();save();}cinemaUpdateSubtitle();const lab=$('#cinSubState');if(lab)lab.textContent='字幕 '+cues.length;return cues.length;}
function cinemaAsrDiscountPct(seconds){seconds=Math.max(0,Number(seconds)||0);return seconds>=7200?10:seconds>=3600?8:seconds>=1800?5:0;}
function cinemaAsrEstimate(seconds){seconds=Math.max(0,Number(seconds)||0);const base=Math.max(1,Math.ceil(seconds/sttRelaySecondsPerPoint())),pct=cinemaAsrDiscountPct(seconds),discount=Math.floor(base*pct/100);return{base,pct,discount,net:base-discount};}
function cinemaSubtitleMenu(){const local=!!_cin.videoFile,configured=cinemaSttConfigured(),off=!local||!configured,relay=sttRelayOn(),directOff=off||relay,platform=!!_cin.provider;openModal(`<h3>视频字幕</h3><div class="hint">${platform?'平台官方播放器不允许小手机读取音轨或内置字幕；如果你有对应的 SRT / VTT，可以手动导入后让角色按时间轴理解已播放内容。':'智能提取会流式读取 MP4 / MOV 音轨，按约 1.5 分钟切段。已完成的分段保存在本机，再次打开只恢复结果，不重复请求、不重复扣点。'+(relay?' 每 '+sttRelaySecondsPerPoint()+' 秒 1 点；累计 30 / 60 / 120 分钟后分别返还约 5% / 8% / 10% 长片优惠。':'')}</div>${platform?'':`<button class="btn p" style="margin-top:10px;width:100%" ${off?'disabled':''} onclick="closeModal();cinemaExtractAudioSubtitles(90,'watch')">边看边提取（推荐）</button><button class="btn g" style="margin-top:8px;width:100%" ${off?'disabled':''} onclick="closeModal();cinemaExtractAudioSubtitles(90,'background')">后台提取，完成后再看</button>`}<div class="btns"><button class="btn g" onclick="closeModal();cinemaPickSubtitle()">导入 SRT / VTT</button>${platform?'':`<button class="btn g" ${directOff?'disabled':''} onclick="closeModal();cinemaExtractSubtitles()">直接上传原视频</button>`}</div>${platform?'<div class="hint">未导入字幕时，角色只知道片名和当前播放时间，不会假装看见受保护的画面。</div>':!local?'<div class="hint">在线视频直链暂不能整段提取，请使用本地视频或导入字幕文件。</div>':!configured?'<div class="hint">提取前，请在设置里配置外置语音转文字接口。</div>':relay?'<div class="hint">90 秒一段通常扣 6 点；总费用仍按实际音频时长计算。失败段自动退点，续提不会重复扣已完成段。</div>':'<div class="hint">外置接口由对应平台计费；长片优惠只适用于小手机内置识别。</div>'}`);}
function cinemaManualSubtitleKey(s){return cinemaStoreKey('subtitle-file',s&&s.mediaKey||_cin.mediaKey||'');}
function cinemaPickSubtitle(){const accept=privateNativeAppOn()?'':'.srt,.vtt,text/vtt,application/x-subrip,text/plain';pickFile(accept,async f=>{try{if(!f||f.size>20*1024*1024)throw new Error('字幕文件不能超过 20 MB');const cues=cinemaParseSubtitles(cinemaDecodeText(await f.arrayBuffer()));if(!cues.length)throw new Error('没有识别到 SRT / VTT 时间轴，请确认文件不是 ASS、LRC 或纯文本');const name=f.name||'手动导入字幕',n=cinemaApplyCues(cues,name,'subtitle'),s=cinemaSession();if(s&&s.mediaKey)await cinPut(cinemaManualSubtitleKey(s),{version:1,name,cues,updatedAt:Date.now()});cinemaSetStatus('字幕已导入并保存 · '+n+' 句','ready');toast('字幕已连接：共 '+n+' 句，已按原时间轴对齐');}catch(e){cinemaSetStatus('字幕导入失败','error');toast((e&&e.message)||'字幕读取失败');}});}
function cinemaSetStatus(text,state,owner){owner=owner||'normal';if(owner!=='vision'&&(_cin.visionBusy||Date.now()<Number(_cin.statusLockUntil||0))){_cin.statusDeferred={text:text||'',state:state||''};return;}if(owner==='vision')_cin.statusLockUntil=Date.now()+(state==='working'?2500:2200);const status=$('#cinContextStatus');if(!status)return;clearTimeout(_cin.statusTimer);status.textContent=text||'';status.classList.toggle('working',state==='working');status.classList.toggle('ready',state==='ready');status.classList.toggle('error',state==='error');if(state==='ready')_cin.statusTimer=setTimeout(()=>{if(status.isConnected){status.textContent='';status.classList.remove('ready','working','error');}},owner==='vision'?2200:1200);}
function cinemaResumeDeferredStatus(){const wait=Math.max(0,Number(_cin.statusLockUntil||0)-Date.now());if(_cin.visionBusy||wait>0){setTimeout(cinemaResumeDeferredStatus,Math.max(60,wait+20));return;}const next=_cin.statusDeferred;_cin.statusDeferred=null;if(next)cinemaSetStatus(next.text,next.state);}
function cinemaExtractHelp(){cinemaSetStatus('提取字幕未配置 · 点提取字幕查看说明','error');openModal('<h3>提取字幕需要先配置</h3><div class="hint">请在设置 → 语音转文字中填写自己的外置接口并测试。<br><br>“压缩音频后提取”只把本地临时音频段交给识别接口，不上传影片画面，也不是播放时持续转写。</div><div class="btns"><button class="btn g" onclick="closeModal()">知道了</button><button class="btn p" onclick="closeModal();cinemaLeaveImmersive();go(\'settings\')">去设置</button></div>');}
function cinemaAudioContext(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('当前浏览器不能读取视频音轨，请改用导入字幕或直接上传原视频');return new AC();}
function cinemaWavAscii(view,offset,text){for(let i=0;i<text.length;i++)view.setUint8(offset+i,text.charCodeAt(i));}
async function cinemaAudioChunkWav(audio,start,end,rate){rate=rate||16000;const frames=Math.max(1,Math.ceil((end-start)*rate)),buf=new ArrayBuffer(44+frames*2),view=new DataView(buf),channels=[];for(let c=0;c<audio.numberOfChannels;c++)channels.push(audio.getChannelData(c));cinemaWavAscii(view,0,'RIFF');view.setUint32(4,36+frames*2,true);cinemaWavAscii(view,8,'WAVE');cinemaWavAscii(view,12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);cinemaWavAscii(view,36,'data');view.setUint32(40,frames*2,true);const base=start*audio.sampleRate,ratio=audio.sampleRate/rate;for(let i=0;i<frames;i++){const pos=Math.min(audio.length-1,base+i*ratio),lo=Math.max(0,Math.floor(pos)),hi=Math.min(audio.length-1,lo+1),mix=pos-lo;let sample=0;for(const data of channels)sample+=(data[lo]||0)*(1-mix)+(data[hi]||0)*mix;sample=Math.max(-1,Math.min(1,sample/Math.max(1,channels.length)));view.setInt16(44+i*2,sample<0?sample*32768:sample*32767,true);if(i&&i%320000===0)await new Promise(resolve=>setTimeout(resolve,0));}return new Blob([buf],{type:'audio/wav'});}
let _cinMp4Module=null;
function cinemaAsrJobKey(s){return cinemaStoreKey('asr-job',s&&s.mediaKey||'');}
function cinemaAsrJobCues(job){const parts=job&&job.parts&&typeof job.parts==='object'?job.parts:{};return Object.keys(parts).sort((a,b)=>Number(a)-Number(b)).flatMap(k=>Array.isArray(parts[k]&&parts[k].cues)?parts[k].cues:[]).sort((a,b)=>a.start-b.start);}
function cinemaAsrNewJob(s,pipeline,duration){return{version:1,pipeline,mediaKey:s.mediaKey,jobId:'cin_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,11),duration:Math.max(0,Number(duration)||0),totalSegments:0,parts:{},status:'working',startedAt:Date.now(),updatedAt:Date.now()};}
async function cinemaAsrLoadJob(s,pipeline){const job=await cinGet(cinemaAsrJobKey(s));return job&&job.version===1&&job.mediaKey===s.mediaKey&&(!pipeline||job.pipeline===pipeline)?job:null;}
function cinemaAsrContiguousSeconds(job){const parts=Object.values(job&&job.parts&&typeof job.parts==='object'?job.parts:{}).filter(x=>x&&Number.isFinite(Number(x.start))&&Number.isFinite(Number(x.end))).sort((a,b)=>Number(a.start)-Number(b.start));let covered=0;for(const part of parts){const start=Math.max(0,Number(part.start)||0),end=Math.max(start,Number(part.end)||0);if(start>covered+1.5)break;covered=Math.max(covered,end);}return Math.min(Math.max(0,Number(job&&job.duration)||covered),covered);}
async function cinemaAsrSaveJob(s,job){const exists=()=>!!(s&&s.mediaKey&&(cinemaInit().library||[]).some(x=>x&&x.mediaKey===s.mediaKey));if(!exists())return null;job.updatedAt=Date.now();try{if(navigator.storage&&navigator.storage.persist)await navigator.storage.persist();}catch(_){}if(!exists())return null;await cinPut(cinemaAsrJobKey(s),job);if(!exists()){await cinDel(cinemaAsrJobKey(s));return null;}cinemaAsrTaskUpdate(s,job);return job;}
function cinemaAsrGuardSync(job,finished){const covered=finished?Math.max(0,Number(job&&job.duration)||0):cinemaAsrContiguousSeconds(job),v=$('#cinVideo');_cin.asrCoveredUntil=covered;if(_cin.asrGuardPaused&&v&&(finished||covered>(v.currentTime||0)+15)){_cin.asrGuardPaused=false;cinemaSetStatus(finished?'完整字幕已就绪，继续播放':'字幕已追上，继续播放','ready');v.play().catch(()=>{});}return covered;}
function cinemaAsrGuardPlayback(v){if(!v||!_cin.extracting||_cin.asrMode!=='watch')return false;const covered=Math.max(0,Number(_cin.asrCoveredUntil)||0),limit=covered>0?Math.max(0,covered-10):20,current=Math.max(0,Number(v.currentTime)||0);if(current<limit-.15)return false;if(v.paused&&!_cin.asrGuardPaused)return false;if(current>limit+.25)v.currentTime=limit;_cin.asrGuardPaused=true;v.pause();cinemaSetStatus('已暂停等字幕 · 当前可看到 '+cinemaFmt(covered||limit),'working');return true;}
