async function cinemaExtractSubtitles(){if(sttRelayOn())return toast('内置识别不会上传原视频，请使用“压缩音频后提取”');const f=_cin.videoFile,s=cinemaSession();if(!f||!s){cinemaSetStatus('只能提取已导入的本地视频','error');return toast('一键提取只支持已导入的本地视频');}if(!cinemaSttConfigured())return cinemaExtractHelp();if(_cin.extracting)return toast('字幕正在提取，请稍候');const size=+f.size||0,tip=size?('视频约 '+Math.max(1,Math.round(size/1048576))+'MB。'):'';if(!await uiConfirm(tip+'将上传整段视频到你配置的语音转文字接口并可能产生费用，确定提取带时间轴字幕？'))return;_cin.extracting=true;const b=$('#cinExtractBtn');if(b){b.classList.add('on');b.disabled=true;const t=b.querySelector('span');if(t)t.textContent='提取中…';}cinemaSetStatus('正在提取整段视频字幕…','working');try{const cues=await sttTranscribeTimed(f,f.name||((s.title||'video')+'.'+((f.type||'').includes('webm')?'webm':'mp4')));if(!cues.length)throw new Error('接口没有返回分段时间戳；请换用支持 verbose_json/segments 的转写模型');const n=cinemaApplyCues(cues,'一键提取字幕','extract');cinemaSetStatus('已提取 '+n+' 句字幕 · 时间轴已对齐','ready');toast('已提取 '+n+' 句字幕，并与视频时间点对齐');}catch(e){cinemaSetStatus('字幕提取失败 · 可重试或导入 SRT / VTT','error');toast((e&&e.message)||'视频字幕提取失败');}finally{_cin.extracting=false;if(b&&b.isConnected){b.disabled=false;b.classList.remove('on');const t=b.querySelector('span');if(t)t.textContent='提取字幕';}}}
function cinemaLogHTML(s){const c=getC(s&&s.cid),items=(s&&s.items||[]).slice(-60);if(!items.length)return '<div class="cin-chat-empty"><b>同屏对话</b><span>开始播放后，直接和 '+cinemaRoleName(c)+' 聊这一幕。</span></div>';return items.map(m=>`<div class="cin-log ${m.who==='me'?'mine':'role'}"><span>${m.who==='me'?'我':cinemaRoleName(c)}</span><p>${esc(m.text).replace(/\n/g,'<br>')}</p><time>${s.kind==='video'?cinemaFmt(m.at||0):'第 '+((m.page||0)+1)+' 页'}</time></div>`).join('');}
function cinemaVisionIntervalLabel(){const set=cinemaInit().settings,n=set.visionInterval,labels={30:'30秒',60:'1分钟',120:'2分钟',150:'2分30秒',300:'5分钟',600:'10分钟'};if(!set.visionEnabled)return'画面关闭';return set.autoVision?('画面 '+(labels[n]||cinemaFmt(n))):'画面按需';}
function cinemaVoiceLangLabel(c){const x=cinemaInit(),v=x.settings.voiceLang,map={role:'跟随角色',zh:'中文',yue:'粤语',en:'英语',ja:'日语',ko:'韩语',fr:'法语',de:'德语',ru:'俄语'};return map[v]||map.role;}
function cinemaReplyCount(){return Math.max(1,Math.min(5,+cinemaInit().settings.replyCount||1));}
function cinemaRandomReplyCount(){const limit=cinemaReplyCount();return limit<=1?1:1+Math.floor(Math.random()*limit);}
function cinemaCompanionMode(){const v=cinemaInit().settings.companionMode;return v==='quiet'||v==='lively'?v:'soft';}
function cinemaCompanionLabel(){const v=cinemaCompanionMode();return v==='quiet'?'安静陪伴':v==='lively'?'活跃陪伴':'轻声陪伴';}
function cinemaAutoLimit(){return Math.max(0,Math.min(20,+cinemaInit().settings.autoLimit||0));}
function cinemaAutoGap(){const v=cinemaCompanionMode();return v==='lively'?115:v==='soft'?230:999999;}
function cinemaCanAutoSpeak(s){const set=cinemaInit().settings;if(!s||cinemaCompanionMode()==='quiet')return false;return (s.autoCount||0)<cinemaAutoLimit();}
function cinemaCommentDisplay(){return cinemaInit().settings.commentDisplay==='subtitle'?'subtitle':'barrage';}
function cinemaCaptionSpeed(){const v=cinemaInit().settings.captionSpeed;return v==='faster'||v==='slower'||v==='slowest'?v:'base';}
